#include "helper.h"
#include <unistd.h>

long helper_page_size(void) {
    return sysconf(_SC_PAGESIZE);
}

const char *helper_platform(void) {
#if defined(__linux__)
    return "linux";
#elif defined(__APPLE__)
    return "macos";
#else
    return "unknown";
#endif
}

ssize_t helper_write_all(int fd, const void *buf, size_t count) {
    const char *p = buf;
    size_t left = count;
    while (left > 0) {
        ssize_t n = write(fd, p, left);
        if (n < 0) {
            return -1;
        }
        p += n;
        left -= (size_t)n;
    }
    return (ssize_t)count;
}
```

main.rs demonstrating FFI with libc types and extern "C":

```rust
use std::ffi::CStr;
use std::io::Write;
use std::os::raw::{c_char, c_int, c_long};

extern "C" {
    fn helper_page_size() -> c_long;
    fn helper_platform() -> *const c_char;
    fn helper_write_all(fd: c_int, buf: *const std::ffi::c_void, count: usize) -> isize;
}

fn main() {
    unsafe {
        let page = helper_page_size();
        let platform = CStr::from_ptr(helper_platform());
        println!("platform: {:?}", platform);
        println!("page size: {page}");

        let msg = b"hello from C write(2)\n";
        helper_write_all(libc::STDOUT_FILENO, msg.as_ptr().cast(), msg.len());

        let pid = libc::getpid();
        let uid = libc::getuid();
        println!("pid={pid} uid={uid}");
    }

    std::io::stdout().flush().unwrap();
}
```

