#ifndef SYS_TOOL_HELPER_H
#define SYS_TOOL_HELPER_H

#include <stddef.h>
#include <sys/types.h>

long helper_page_size(void);
const char *helper_platform(void);
ssize_t helper_write_all(int fd, const void *buf, size_t count);

#endif

#include "helper.h"

#include <unistd.h>

long helper_page_size(void) {
    return sysconf(_SC_PAGESIZE);
}

const char *helper_platform(void) {
#if defined(__linux__)
    return "linux";
#elif defined(__APPLE__)
    return "macos";
#elif defined(_WIN32)
    return "windows";
#else
    return "unknown";
#endif
}

ssize_t helper_write_all(int fd, const void *buf, size_t count) {
    const char *p = buf;
    size_t left = count;

    while (left > 0) {
        ssize_t n = write(fd, p, left);
        if (n < 0) {
            return -1;
        }
        p += n;
        left -= (size_t)n;
    }

    return (ssize_t)count;
}

use std::ffi::{CStr, c_void};
use std::io::Write;
use std::os::raw::{c_char, c_int, c_long};

extern "C" {
    fn helper_page_size() -> c_long;
    fn helper_platform() -> *const c_char;
    fn helper_write_all(fd: c_int, buf: *const c_void, count: usize) -> isize;
}

fn main() {
    unsafe {
        let platform = CStr::from_ptr(helper_platform());
        let page_size = helper_page_size();
        println!("platform:  {}", platform.to_string_lossy());
        println!("page size: {page_size}");

        let msg = b"written via the bundled C library\n";
        let written = helper_write_all(libc::STDOUT_FILENO, msg.as_ptr().cast(), msg.len());
        assert_eq!(written as usize, msg.len());

        let pid = libc::getpid();
        let uid = libc::getuid();
        println!("pid:       {pid}");
        println!("uid:       {uid}");
    }

    std::io::stdout().flush().unwrap();
}

